// ── Extract delivery status from Chatwoot message_updated webhook ──────────
const body = $json.body;
const sourceId = body.source_id;

if (!sourceId) return [];

// Find the specific message in the messages array that matches this source_id
const messages = body?.conversation?.messages || [];
const targetMsg = messages.find(m => m.source_id === sourceId);

if (!targetMsg) return [];

const deliveryStatus = targetMsg.status;

// Only proceed for real WhatsApp delivery status events
const validStatuses = ['sent', 'delivered', 'read', 'failed'];
if (!validStatuses.includes(deliveryStatus)) return [];

// Phone without + prefix — matches your Customer Profiles sheet format
const phoneWithPlus = body?.conversation?.meta?.sender?.phone_number || '';
const phoneRaw = phoneWithPlus.replace('+', '');

return [{
  json: {
    wamid: sourceId,
    delivery_status: deliveryStatus,
    phone_raw: phoneRaw,
    chatwoot_msg_id: body.id || null
  }
}];

